# Critical path dependency mapping example (simplified)
from datetime import datetime, timedelta

tasks = {
    'data_governance': {'duration': 90, 'dependencies': []},
    'infrastructure': {'duration': 120, 'dependencies': []},
    'pilot_1': {'duration': 60, 'dependencies': ['data_governance']},
    'pilot_2': {'duration': 75, 'dependencies': ['data_governance', 'infrastructure']},
    'scale_deployment': {'duration': 180, 'dependencies': ['pilot_1', 'pilot_2']}
}

# Calculate earliest start dates
start_dates = {}
for task, details in tasks.items():
    if not details['dependencies']:
        start_dates[task] = 0
    else:
        dep_ends = [start_dates[d] + tasks[d]['duration'] for d in details['dependencies']]
        start_dates[task] = max(dep_ends)

print("Critical Path Timeline (days from start):")
for task, start in sorted(start_dates.items(), key=lambda x: x[1]):
    end = start + tasks[task]['duration']
    print(f"{task}: Day {start} -> Day {end}")
